It would be convenient for jax.Array to have the equivalent of the torch.Tensor.flatten method. (For example, when flattening an input with arbitrary batch dimensions in a convolutional neural network.) Here is an example implementation:
from jax import numpy as jnp, Array

def flatten_axes(a: Array, start: int = 0, end: int = -1) -> Array:
    return a.reshape(a.shape[:start] + (-1,) + a.shape[end:][1:])

def main():
    a = jnp.arange(2 * 3 * 4 * 5 * 6).reshape(2, 3, 4, 5, 6)
    assert flatten_axes(a, 1, -2).shape == (2, 3 * 4 * 5, 6)
    assert flatten_axes(a, -3).shape == (2, 3, 4 * 5 * 6)

if __name__ == '__main__':
    main()
